/**
 * @brief Copy a bounded rectangular leased tile-map region without replacing the whole plane.
 * @param lease Borrowed current exclusive graphics token.
 * @param plane Zero for foreground A, one for background B.
 * @param x First screen tile column, 0..39.
 * @param y First screen tile row, 0..27.
 * @param width Nonzero region width, at most 40 minus x.
 * @param height Nonzero region height, at most 28 minus y.
 * @param cells Borrowed width times height uint16 attributes, contiguous row-major; low 11 bits are
 * relative to lease first_tile, upper bits retain priority/palette/flip attributes.
 * @return MB_OK or MB_INVALID.
 * @note Errors: Stale lease, null cells, invalid plane/bounds or any out-of-range pattern
 * MB_INVALID; whole region validated before changes.
 * @note Ownership/lifetime: Cells copied synchronously into OS retained maps; source may be reused
 * immediately. No heap or new retained workspace.
 * @note Callback context: Foreground callbacks only; normal bounded plane flush commits dirty cells
 * after VBlank. Unchanged cells remain clean.
 * @note Hardware/capability: API 1.7 exclusive graphics lease; efficient incremental animation on
 * either plane.
 * @since 1.7
 */
MB_Result mb_graphics_map_region(const MB_PaletteLease *lease, uint16_t plane, uint16_t x,
                                 uint16_t y, uint16_t width, uint16_t height,
                                 const uint16_t *cells);

/**
 * @brief Copy an app-defined cursor bitmap and hotspot for its client area or canvas.
 * @param cursor Borrowed synchronously; non-null descriptor with dimensions 1..16 screen pixels and
 * hotspot within those dimensions. Each uint32 row stores sixteen left-aligned 2-bit pixels: 0
 * transparent, 1 dark, 2 light, 3 accent. Outside declared dimensions is ignored.
 * @param scope MB_CURSOR_CLIENT applies inside the client rectangle in pointer mode;
 * MB_CURSOR_CANVAS follows the logical drawing point on an attached source canvas.
 * @return MB_OK, MB_INVALID, MB_UNAVAILABLE or MB_BUSY.
 * @note Errors: Invalid pointer/dimensions/hotspot/scope MB_INVALID; no active app/window or
 * required source canvas MB_UNAVAILABLE; exclusive graphics lease MB_BUSY. Failures preserve the
 * current cursor.
 * @note Ownership/lifetime: Descriptor and all sixteen rows copied into one fixed OS workspace.
 * Caller may immediately change or release its bitmap; no heap or hardware ownership. Reset
 * automatically on app close/window reset/OS restart.
 * @note Callback context: Foreground callbacks only. Four patterns (128 VRAM bytes) upload during
 * the next video flush; motion only changes sprite positions. Last set before a flush wins.
 * @note Hardware/capability: API 1.7. Four OS pointer sprites, reserved patterns and semantic PAL3
 * colours. No SGDK calls required from apps.
 * @since 1.7
 */
MB_Result mb_cursor_set(const MB_Cursor *cursor, uint16_t scope);

/**
 * @brief Restore the normal OS or canvas cursor and cancel a pending custom upload.
 * @return None.
 * @note Errors: None; repeated calls are harmless.
 * @note Ownership/lifetime: Releases the app's cursor selection; OS retains its fixed workspace and
 * patterns.
 * @note Callback context: Foreground callbacks; visibility returns to normal on the next pointer
 * update.
 * @note Hardware/capability: API 1.7; safe without an active app and while graphics are leased.
 * @since 1.7
 */
void mb_cursor_reset(void);

/**
 * @brief Add a one-tile-high menu item in client row zero using shared focus, hover and activation.
 * @param id Unique widget ID other than 65535. MB_UI_MENU_DISMISS is reserved and cannot be
 * registered.
 * @param x Client-relative starting tile column.
 * @param width At least three tiles, wholly within the queried client.
 * @param label Borrowed ASCII label, copied and clipped to width minus two, at most eleven
 * characters.
 * @param flags Zero for disabled, MB_UI_ENABLED, or MB_UI_ENABLED | MB_UI_MENU_OPEN for the
 * currently open heading.
 * @return MB_OK, MB_INVALID or MB_BUSY.
 * @note Errors: Invalid bounds, null label, duplicate ID or flags MB_INVALID; full 24-widget pool
 * MB_BUSY.
 * @note Ownership/lifetime: OS copies label; occupies one existing widget slot, reset by
 * mb_ui_reset/window clear.
 * @note Callback context: Foreground callbacks only; retained tiles flush at VBlank.
 * @note Hardware/capability: Shared one-row app menus; no allocation or separate UI framework.
 * @since 1.6
 */
MB_Result mb_ui_menu_button(uint16_t id, uint16_t x, uint16_t width, const char *label,
                            uint16_t flags);

/**
 * @brief Query drawable content in absolute screen tiles after reserving an optional single app
 * menu row.
 * @param menu_rows Zero for no menu or one for a compact menu directly below the header.
 * @param out Caller-owned non-null rectangle; screen coordinates in 8x8 tiles.
 * @return MB_OK, MB_INVALID or MB_UNAVAILABLE.
 * @note Errors: Null output or menu_rows greater than one MB_INVALID; no open window
 * MB_UNAVAILABLE.
 * @note Ownership/lifetime: Snapshot only; no allocation or retained pointer.
 * @note Callback context: Foreground callbacks; query again on MB_RESIZE or MB_MODE_CHANGED.
 * @note Hardware/capability: Normal, maximized and fullscreen geometry. Maximized with a menu
 * returns (0,2,40,26), or 320x208 pixels.
 * @since 1.6
 */
MB_Result mb_window_get_content_rect(uint16_t menu_rows, MB_Rect *out);

/**
 * @brief Query whether attached tile canvas and retained window uploads are complete.
 * @return MB_OK when the current canvas, palette and retained maps are flushed; MB_BUSY while
 * pending; MB_UNAVAILABLE without an attached canvas.
 * @note Errors: Missing attached canvas returns MB_UNAVAILABLE.
 * @note Ownership/lifetime: Reads OS-owned bounded upload metadata; no allocation or mutation.
 * @note Callback context: Foreground app callbacks only; observes the previous VBlank flush.
 * Bounded scan of at most 140 dirty bytes.
 * @note Hardware/capability: Native H40 attached canvas on PAL and NTSC.
 * @since 1.6
 */
MB_Result mb_canvas_ready(void);
#endif
